ruleContent.content:
js:
var doc = java.jsoup.parse(result);
var content = doc.select("#content").first();
content ? content.text().replace(/\s{2,}/g,'\n').trim() : '';

ruleToc.chapterList:
js:
var doc = java.jsoup.parse(result);
var chapters = [];
doc.select(".chapterlist a, #chapterlist a, .list a").forEach(function(el) {
    chapters.push({
        "title": el.text().trim(),
        "url": "https://m.bugexs.com" + el.attr("href")
    });
});
JSON.stringify(chapters);
